#include <stdio.h>
#include <ctype.h>
#include <string.h>

static int soundex_digit(char ch)
{
    switch (ch) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default: return 0;
    }
}

int main(int argc, char *argv[])
{
    const char *input;
    char code[5];
    int digit_count = 0;
    int prev_digit;
    size_t i, len;

    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    input = argv[1];
    len = strlen(input);
    if (len == 0) {
        puts("EMPTY");
        return 0;
    }
    code[0] = (char)toupper((unsigned char)input[0]);
    prev_digit = soundex_digit(code[0]);
    for (i = 1; i < len && digit_count < 3; ++i) {
        char c = (char)toupper((unsigned char)input[i]);
        if (c == 'H' || c == 'W')
            continue;
        int d = soundex_digit(c);
        if (d == 0)
            continue;
        if (d == prev_digit)
            continue;
        code[1 + digit_count] = (char)('0' + d);
        ++digit_count;
        prev_digit = d;
    }
    while (digit_count < 3) {
        code[1 + digit_count] = '0';
        ++digit_count;
    }
    code[4] = '\0';
    puts(code);
    return 0;
}
